 <section class="pages-hero-v2"><div class="pages-title-v2"><b>▤</b><div><span>KELOLA KONTEN</span><h1>Halaman &amp; Menu</h1><p>Halaman yang ditandai tampil di menu akan muncul di navigasi website.</p></div></div><div class="pages-art-v2" aria-hidden="true"><i class="browser"><b></b><b></b><b></b><em></em></i><i class="globe">◎</i></div></section>
 <form class="pages-filter-v2" method="get" action="<?= site_url('admin/pages') ?>"><label class="pages-search-v2"><span>⌕</span><input type="search" name="q" value="<?= html_escape($q) ?>" placeholder="Cari judul halaman atau URL..."></label><label><span>▦</span><select name="status"><option value="" <?= $status===''?'selected':'' ?>>Semua Status</option><option value="published" <?= $status==='published'?'selected':'' ?>>Terbit</option><option value="draft" <?= $status==='draft'?'selected':'' ?>>Draf</option><option value="menu" <?= $status==='menu'?'selected':'' ?>>Tampil di Menu</option></select></label><label><span>⇅</span><select name="sort"><option value="order" <?= $sort==='order'?'selected':'' ?>>Urutan Menu</option><option value="title" <?= $sort==='title'?'selected':'' ?>>Urutan A–Z</option><option value="newest" <?= $sort==='newest'?'selected':'' ?>>Terbaru</option></select></label><button type="submit">Filter</button><a class="pages-add-v2" href="<?= site_url('admin/page') ?>">＋ &nbsp; Tambah Halaman</a></form>
 <section class="pages-table-v2"><div><table><thead><tr><th>No</th><th>Judul Halaman</th><th>URL</th><th>Urutan</th><th>Tampil di Menu</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($pages as $index=>$page): ?><tr><td><?= $index+1 ?></td><td><span class="page-title-cell-v2"><b>⌂</b><span><strong><?= html_escape($page['title']) ?></strong><small><?= html_escape(mb_strimwidth(trim(preg_replace('/\s+/u',' ',strip_tags($page['body']))),0,90,'…')) ?></small></span></span></td><td><a class="page-url-v2" href="<?= site_url('halaman/'.$page['slug']) ?>" target="_blank" rel="noopener">/<?= html_escape($page['slug']) ?></a></td><td><span class="page-order-v2"><?= (int)$page['sort_order'] ?></span></td><td><span class="page-menu-v2 <?= $page['show_in_menu']?'yes':'no' ?>"><i></i><?= $page['show_in_menu']?'Ya':'Tidak' ?></span></td><td><span class="page-status-v2 <?= $page['is_published']?'published':'draft' ?>"><i></i><?= $page['is_published']?'Terbit':'Draf' ?></span></td><td><div class="page-actions-v2"><a class="edit" href="<?= site_url('admin/page/'.$page['id']) ?>">✎ &nbsp; Edit</a><form method="post" action="<?= site_url('admin/delete_page/'.$page['id']) ?>" onsubmit="return confirm('Hapus halaman ini?')"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><button type="submit">▣ &nbsp; Hapus</button></form></div></td></tr><?php endforeach; ?><?php if(!$pages): ?><tr><td colspan="7" class="pages-empty-v2">Tidak ada halaman yang cocok dengan pencarian atau filter.</td></tr><?php endif; ?></tbody></table></div><footer>Menampilkan <?= count($pages) ?> dari <?= (int)$total ?> halaman</footer></section>
